import { StrictMode, useCallback, useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { fetchFindings } from './api/findings'
import { mapFindingToListItem } from './api/mapFindingToListItem'
import { mapRepoToListItem } from './api/mapRepoToListItem'
import { mapRepoToMapPoint } from './api/mapRepoToMapPoint'
import { mapRepoToSidebar } from './api/mapRepoToSidebar'
import { fetchRepo, fetchRepos } from './api/repos'
import type { FindingListEntry } from './api/types'
import {
  FindingsView,
  type FindingsRiskFilter,
} from './components/FindingsView'
import { FavouritesSidebar } from './components/FavouritesSidebar'
import { GalaxyMap } from './components/GalaxyMap'
import {
  MapSearchBar,
  type MapSearchScope,
} from './components/MapSearchBar'
import {
  RepoListSidebar,
  type RepoListItem,
} from './components/RepoListSidebar'
import { RepoSidebar, type RepoSidebarProps } from './components/RepoSidebar'
import { SidebarPanel } from './components/SidebarPanel'
import { TopNavbar, type TopNavbarTab } from './components/TopNavbar'
import { useFavourites } from './favourites/useFavourites'
import type { MapRepo } from './map/types'
import { useMapCamera } from './map/useMapCamera'
import './styles.css'

function App() {
  const [repos, setRepos] = useState<RepoListItem[]>([])
  const [mapRepos, setMapRepos] = useState<MapRepo[]>([])
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const mapCamera = useMapCamera()

  const [findings, setFindings] = useState<FindingListEntry[]>([])
  const [findingsError, setFindingsError] = useState<string | null>(null)
  const [findingsLoading, setFindingsLoading] = useState(false)
  const [riskFilter, setRiskFilter] = useState<FindingsRiskFilter>('all')

  const [tab, setTab] = useState<TopNavbarTab>('map')
  const [sidebarWidth, setSidebarWidth] = useState(580)
  const [searchQuery, setSearchQuery] = useState('')
  const [searchScope, setSearchScope] = useState<MapSearchScope>('all')

  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [detail, setDetail] = useState<RepoSidebarProps | null>(null)
  const [detailLoading, setDetailLoading] = useState(false)
  const [detailError, setDetailError] = useState<string | null>(null)
  const [view, setView] = useState<'list' | 'detail'>('list')
  const [listMode, setListMode] = useState<'browse' | 'saved'>('browse')
  const favourites = useFavourites()

  useEffect(() => {
    const controller = new AbortController()
    setLoading(true)
    setError(null)
    fetchRepos(controller.signal)
      .then((entries) => {
        setRepos(entries.map(mapRepoToListItem))
        setMapRepos(
          entries
            .map(mapRepoToMapPoint)
            .filter((point): point is MapRepo => point != null),
        )
        setLoading(false)
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted) return
        const message = err instanceof Error ? err.message : 'Failed to load repos'
        setError(message)
        setLoading(false)
      })
    return () => controller.abort()
  }, [])

  useEffect(() => {
    if (tab !== 'findings') return
    const controller = new AbortController()
    setFindingsLoading(true)
    setFindingsError(null)
    fetchFindings(
      riskFilter === 'all' ? {} : { risk: riskFilter },
      controller.signal,
    )
      .then((rows) => {
        setFindings(rows)
        setFindingsLoading(false)
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted) return
        const message = err instanceof Error ? err.message : 'Failed to load findings'
        setFindingsError(message)
        setFindingsLoading(false)
      })
    return () => controller.abort()
  }, [tab, riskFilter])

  useEffect(() => {
    if (!selectedId) {
      setDetail(null)
      setDetailError(null)
      setDetailLoading(false)
      setView('list')
      return
    }

    setView('detail')
    const controller = new AbortController()
    setDetailLoading(true)
    setDetailError(null)
    fetchRepo(selectedId, controller.signal)
      .then((repo) => {
        setDetail(mapRepoToSidebar(repo))
        setDetailLoading(false)
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted) return
        const message = err instanceof Error ? err.message : 'Failed to load repo'
        setDetail(null)
        setDetailError(message)
        setDetailLoading(false)
      })
    return () => controller.abort()
  }, [selectedId])

  const findingListItems = useMemo(
    () => findings.map(mapFindingToListItem),
    [findings],
  )

  const filteredRepos = useMemo(() => {
    const q = searchQuery.trim().toLowerCase()
    if (!q) return repos
    return repos.filter((repo) => {
      const name = repo.name.toLowerCase()
      const category = repo.category.toLowerCase()
      const description = repo.description.toLowerCase()
      if (searchScope === 'name') return name.includes(q)
      if (searchScope === 'category') return category.includes(q)
      if (searchScope === 'language') {
        return description.includes(q) || name.includes(q)
      }
      return name.includes(q) || category.includes(q) || description.includes(q)
    })
  }, [repos, searchQuery, searchScope])

  const { setViewportSize, fitToRepos, pan, zoomIn, zoomOut, zoomByFactor, camera } =
    mapCamera

  useEffect(() => {
    if (mapRepos.length === 0) return
    fitToRepos(mapRepos)
  }, [mapRepos, fitToRepos])

  const handleViewportChange = useCallback(
    (width: number, height: number) => {
      setViewportSize(width, height)
      if (mapRepos.length > 0) fitToRepos(mapRepos)
    },
    [fitToRepos, mapRepos, setViewportSize],
  )

  const backLabel =
    listMode === 'saved'
      ? '← Favourites'
      : tab === 'findings'
        ? '← Findings'
        : '← Repositories'

  function handleBack() {
    setSelectedId(null)
  }

  function handleViewSaved() {
    setSelectedId(null)
    setListMode('saved')
    setView('list')
  }

  function handleSelectRepo(id: string) {
    setSelectedId(id)
  }

  function handleTabChange(next: TopNavbarTab) {
    setTab(next)
    setSelectedId(null)
    setListMode('browse')
  }

  let detailPane = null
  if (selectedId) {
    if (detailLoading) {
      detailPane = (
        <aside className="repo-sidebar repo-sidebar--status" aria-busy="true">
          <p>Loading {selectedId}…</p>
          <button type="button" className="repo-sidebar__back" onClick={handleBack}>
            {backLabel}
          </button>
        </aside>
      )
    } else if (detailError) {
      detailPane = (
        <aside className="repo-sidebar repo-sidebar--status" role="alert">
          <p>Could not load {selectedId}.</p>
          <p className="repo-sidebar__error-detail">{detailError}</p>
          <button type="button" className="repo-sidebar__back" onClick={handleBack}>
            {backLabel}
          </button>
        </aside>
      )
    } else if (detail) {
      detailPane = (
        <RepoSidebar
          {...detail}
          onBack={handleBack}
          backLabel={backLabel}
          onViewSaved={handleViewSaved}
          favouriteLists={favourites.lists}
          isFavourite={favourites.isFavourite(detail.repoId ?? '')}
          favouriteListsForRepo={favourites.listsForRepo(detail.repoId ?? '')}
          onToggleFavourite={favourites.toggleFavourite}
          onToggleInList={favourites.toggleInList}
          onCreateFavouriteList={favourites.createList}
        />
      )
    }
  }

  const listSidebar =
    listMode === 'saved' ? (
      <FavouritesSidebar
        lists={favourites.lists}
        repos={repos}
        selectedId={selectedId}
        onBack={() => setListMode('browse')}
        onSelectRepo={handleSelectRepo}
        onCreateList={favourites.createList}
        onRenameList={favourites.renameList}
        onDeleteList={favourites.deleteList}
        onRemoveFromList={favourites.removeFromList}
      />
    ) : tab === 'findings' ? (
      <RepoListSidebar
        title="Agent Findings"
        metaLabel="Investigation findings"
        scoreLabel="Confidence:"
        categoryLabel="Category:"
        emptyLabel="No headline."
        countLabel={
          findingsLoading
            ? undefined
            : `${findingListItems.length} ${findingListItems.length === 1 ? 'finding' : 'findings'}`
        }
        repos={findingListItems}
        loading={findingsLoading}
        error={findingsError}
        selectedId={selectedId}
        onViewSaved={handleViewSaved}
        onSelectRepo={handleSelectRepo}
      />
    ) : (
      <RepoListSidebar
        repos={filteredRepos}
        loading={loading}
        error={error}
        selectedId={selectedId}
        onViewSaved={handleViewSaved}
        onSelectRepo={handleSelectRepo}
        countLabel={
          searchQuery.trim()
            ? `${filteredRepos.length} of ${repos.length} repositories`
            : undefined
        }
      />
    )

  return (
    <div className="app-shell">
      <div className="app-shell__main">
        <TopNavbar activeTab={tab} onTabChange={handleTabChange} />
        {tab === 'findings' ? (
          <FindingsView
            findings={findings}
            loading={findingsLoading}
            error={findingsError}
            selectedId={selectedId}
            riskFilter={riskFilter}
            onRiskFilterChange={setRiskFilter}
            onSelectFinding={handleSelectRepo}
          />
        ) : (
          <main className="app-shell__map" aria-label="Repository galaxy map">
            <GalaxyMap
              repos={mapRepos}
              camera={camera}
              selectedId={selectedId}
              onSelectRepo={handleSelectRepo}
              onViewportChange={handleViewportChange}
              onPan={pan}
              onZoomByFactor={zoomByFactor}
            />
            <MapSearchBar
              query={searchQuery}
              scope={searchScope}
              results={filteredRepos}
              onQueryChange={setSearchQuery}
              onScopeChange={setSearchScope}
              onSelectResult={handleSelectRepo}
              onZoomIn={() => zoomIn()}
              onZoomOut={() => zoomOut()}
            />
          </main>
        )}
      </div>
      <SidebarPanel width={sidebarWidth} onWidthChange={setSidebarWidth}>
        <div
          className={`sidebar-stack${view === 'detail' ? ' is-detail' : ' is-list'}`}
          aria-live="polite"
        >
          <div className="sidebar-stack__pane sidebar-stack__pane--list">
            {listSidebar}
          </div>
          <div className="sidebar-stack__pane sidebar-stack__pane--detail">
            {detailPane}
          </div>
        </div>
      </SidebarPanel>
    </div>
  )
}

createRoot(document.getElementById('root')!).render(
  <StrictMode><App /></StrictMode>,
)
import type { FindingListEntry } from '../api/types'

export type FindingsRiskFilter = 'all' | 'at_risk' | 'watchlist' | 'healthy' | 'inconclusive'

export type FindingsViewProps = {
  findings?: FindingListEntry[]
  loading?: boolean
  error?: string | null
  selectedId?: string | null
  riskFilter?: FindingsRiskFilter
  onRiskFilterChange?: (risk: FindingsRiskFilter) => void
  onSelectFinding?: (repoId: string) => void
}

function riskClass(risk: string | null | undefined): string {
  const r = (risk || '').toLowerCase()
  if (r === 'at_risk') return 'is-at-risk'
  if (r === 'watchlist') return 'is-watchlist'
  if (r === 'healthy') return 'is-healthy'
  return 'is-inconclusive'
}

function formatRisk(risk: string | null | undefined): string {
  return (risk || 'unknown').replaceAll('_', ' ')
}

function formatDate(iso: string | null | undefined): string {
  if (!iso) return '—'
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return '—'
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

const FILTERS: { id: FindingsRiskFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'at_risk', label: 'At risk' },
  { id: 'watchlist', label: 'Watchlist' },
  { id: 'healthy', label: 'Healthy' },
  { id: 'inconclusive', label: 'Inconclusive' },
]

export function FindingsView({
  findings = [],
  loading = false,
  error = null,
  selectedId = null,
  riskFilter = 'all',
  onRiskFilterChange,
  onSelectFinding,
}: FindingsViewProps) {
  return (
    <section className="findings-view" aria-label="Agent findings">
      <header className="findings-view__header">
        <div className="findings-view__intro">
          <p className="findings-view__eyebrow">Agent output</p>
          <h1 className="findings-view__title">Findings</h1>
          <p className="findings-view__subtitle">
            Investigations sorted by severity. Open a row to inspect the repo in the sidebar.
          </p>
        </div>
        <div className="findings-view__filters" role="toolbar" aria-label="Risk filter">
          {FILTERS.map((filter) => (
            <button
              key={filter.id}
              type="button"
              className={`findings-view__filter${riskFilter === filter.id ? ' is-active' : ''}`}
              aria-pressed={riskFilter === filter.id}
              onClick={() => onRiskFilterChange?.(filter.id)}
            >
              {filter.label}
            </button>
          ))}
        </div>
      </header>

      <div className="findings-view__body">
        {loading ? (
          <p className="findings-view__status">Loading findings…</p>
        ) : error ? (
          <p className="findings-view__status is-error" role="alert">
            {error}
          </p>
        ) : findings.length === 0 ? (
          <p className="findings-view__status">No findings for this filter yet.</p>
        ) : (
          <>
            <p className="findings-view__count">
              {findings.length} {findings.length === 1 ? 'finding' : 'findings'}
            </p>
            <ul className="findings-list">
              {findings.map((finding) => {
                const confidence = Math.round((finding.confidence ?? 0) * 100)
                return (
                  <li key={`${finding.repo_id}-${finding.run_id}`}>
                    <button
                      type="button"
                      className={`findings-row${selectedId === finding.repo_id ? ' is-selected' : ''}`}
                      aria-current={selectedId === finding.repo_id ? 'true' : undefined}
                      onClick={() => onSelectFinding?.(finding.repo_id)}
                    >
                      <div className="findings-row__top">
                        <span className={`status-chip ${riskClass(finding.risk_level)}`}>
                          {formatRisk(finding.risk_level)}
                        </span>
                        {finding.in_latest_run ? (
                          <span className="findings-row__new">New</span>
                        ) : null}
                        <span className="findings-row__meta">
                          {confidence}% confidence · {formatDate(finding.investigated_at)}
                        </span>
                      </div>
                      <p className="findings-row__name">{finding.name || finding.repo_id}</p>
                      <p className="findings-row__headline">
                        {finding.headline || 'No headline.'}
                      </p>
                      <div className="findings-row__footer">
                        <span>{finding.language || '—'}</span>
                        <span>{finding.category || '—'}</span>
                        {finding.changed_since_last ? (
                          <span>{finding.changed_since_last.replaceAll('_', ' ')}</span>
                        ) : null}
                      </div>
                    </button>
                  </li>
                )
              })}
            </ul>
          </>
        )}
      </div>
    </section>
  )
}
import type { FindingListEntry } from './types'

export type FindingsQuery = {
  language?: string
  risk?: string
}

export async function fetchFindings(
  query: FindingsQuery = {},
  signal?: AbortSignal,
): Promise<FindingListEntry[]> {
  const params = new URLSearchParams()
  if (query.language) params.set('language', query.language)
  if (query.risk) params.set('risk', query.risk)
  const qs = params.toString()
  const res = await fetch(`/api/findings${qs ? `?${qs}` : ''}`, { signal })
  if (!res.ok) {
    const detail = await res.text().catch(() => '')
    throw new Error(detail || `Failed to load findings (${res.status})`)
  }
  return res.json() as Promise<FindingListEntry[]>
}
import type { RepoListItem } from '../components/RepoListSidebar'
import type { FindingListEntry } from './types'

function riskTone(risk: string | null | undefined): RepoListItem['vulnerabilityTone'] {
  const r = (risk || '').toLowerCase()
  if (r === 'at_risk') return 'high'
  if (r === 'watchlist') return 'medium'
  if (r === 'inconclusive') return 'low'
  if (r === 'healthy') return 'none'
  return 'low'
}

function riskLabel(risk: string | null | undefined): string {
  const r = (risk || '').toLowerCase()
  if (r === 'at_risk') return 'At risk'
  if (r === 'watchlist') return 'Watchlist'
  if (r === 'inconclusive') return 'Inconclusive'
  if (r === 'healthy') return 'Healthy'
  return risk?.replaceAll('_', ' ') || 'Unknown'
}

export function mapFindingToListItem(finding: FindingListEntry): RepoListItem {
  const tone = riskTone(finding.risk_level)
  const confidence = Math.round((finding.confidence ?? 0) * 100)
  return {
    id: finding.repo_id,
    name: finding.name || finding.repo_id,
    description: finding.headline || finding.explanation || '',
    vulnerabilityLabel: riskLabel(finding.risk_level),
    vulnerabilityTone: tone === 'none' ? 'low' : tone,
    vulnerabilityScore: `${confidence}%`,
    category: finding.category?.trim() || finding.language || '—',
  }
}
export type FindingListEntry = {
  repo_id: string
  name: string | null
  language: string | null
  importance: number | null
  health_score: number | null
  category: string | null
  vuln_buckets: string[]
  run_id: string
  risk_level: string
  confidence: number
  headline: string
  explanation: string
  evidence: unknown[]
  changed_since_last: string | null
  alternatives: string[]
  tool_calls: number
  trace_id: string | null
  investigated_at: string
  in_latest_run: boolean | null
}

export type RepoListEntry = {
  repo_id: string
  name: string
  owner: string
  language: string | null
  health_score: number | null
  status: string | null
  importance: number | null
  stars: number | null
  is_archived: boolean | null
  category: string | null
  vuln_buckets: string[]
  advisory_count: number | null
  max_severity: string | null
  max_cvss: number | null
  risk_level: string | null
  changed_since_last: string | null
  investigated: boolean | null
  investigated_in_latest_run: boolean | null
  summary: string | null
  x: number | null
  y: number | null
  cat_x: number | null
  cat_y: number | null
}

export type EvidenceItem = {
  signal: string
  tool: string
  value: string | number | null
}

export type Verdict = {
  run_id: string
  risk_level: string
  confidence: number
  headline: string
  explanation: string
  evidence: EvidenceItem[]
  changed_since_last: string | null
  alternatives: string[]
  tool_calls: number
  trace_id: string | null
  investigated_at: string
}

export type Advisory = {
  ghsa_id: string
  cve_id: string | null
  severity: string | null
  cvss_score: number | null
  cwes: string[]
  vuln_bucket: string | null
  summary: string | null
  published_at: string | null
}

export type RepoMetrics = {
  days_since_release: number | null
  commit_trend_pct: number | null
  pushed_at: string | null
  last_release_at: string | null
  commits_90d: number | null
  commits_prev_90d: number | null
  open_issues: number | null
  open_prs: number | null
  contributors: number | null
  maintainer_reply_rate: number | null
  top_contributor_share: number | null
}

export type RepoDetail = {
  repo_id: string
  name: string
  owner: string
  language: string | null
  stars: number | null
  dependents: number | null
  is_archived: boolean | null
  health_score: number | null
  status: string | null
  importance: number | null
  category: string | null
  vuln_buckets: string[]
  advisory_count: number | null
  max_severity: string | null
  max_cvss: number | null
