import type { FindingListEntry } from '../api/types'

export type FindingsRiskFilter = 'all' | 'at_risk' | 'watchlist' | 'healthy' | 'inconclusive'

export type FindingsFilters = {
  risk: FindingsRiskFilter
  language: string // 'all' or a language name
}

/** Filters keep the API's order (severity, then importance). */
export function filterFindings(
  findings: FindingListEntry[],
  { risk, language }: FindingsFilters,
): FindingListEntry[] {
  return findings.filter(
    (f) =>
      (risk === 'all' || f.risk_level === risk) &&
      (language === 'all' || f.language === language),
  )
}

export function findingLanguages(findings: FindingListEntry[]): string[] {
  const set = new Set<string>()
  for (const f of findings) if (f.language) set.add(f.language)
  return [...set].sort((a, b) => a.localeCompare(b))
}

